    console.info(
      `[S3 W3 RED/GREEN] churn=${policy.rateLimitBucketCapacity + 10} `
      + `victim_refused=${String(!afterChurn.allowed)} `
      + `occupied=${occupancy.occupiedSlots}/${occupancy.slotCapacity}`
    );

    expect(afterChurn).toEqual({ allowed: false, scope: "ip" });
