  it("S3c C2 derives every beyond-threat point from the exact-binomial full-budget model", () => {
    const rateLimitRow = AUTH_POLICY_REGISTER_ROWS.find((row) => row.rowKey === "rateLimitPolicy")!;
    const curve = (rateLimitRow.value as {
      sketch_design: {
