        duplicatePostworkAuditCount: Number(duplicatePostworkAudits.rows[0]!.count),
        expectedMailCount: existingEmails.length + concurrency * waves,
        mailCount: timingMail.messages.length,
        hashAndProvisioningMaximumMs,
