  readonly limiterHashKey?: Uint8Array;
  readonly verificationTokenFactory?: () => string;
} = {}) {
  let now = input.initialNow ?? new Date("2026-08-19T12:00:00.000Z");
  const policy = input.policy ?? basePolicy;
