  const limiter = new InProcessAuthRateLimiter(
    policy.rateLimits,
    policy.rateLimitBucketCapacity,
    policy.rateLimitRefusalAuditIntervalMs,
    input.limiterHashKey
  );
  const service = new RegistrationService({
    repository,
