      while (!predicate()) {
        if (performance.now() - startedAt > timeoutMs) {
          throw new Error(`S3D_R3_WAIT_TIMEOUT:${label}:${JSON.stringify(
            service.mailDispatchOccupancy()
          )}`);
        }
        await new Promise<void>((resolve) => setTimeout(resolve, 10));
      }
    };

