        + `auc_ceiling_pct=${(aucCeiling * 100).toFixed(1)} ${cells.join(" | ")}`
    );
    for (const measurement of measurements) {
      expect(measurement.medianGapMs).toBeLessThanOrEqual(
        basePolicy.verification.enumerationToleranceMs
      );
