    while (flow.service.mailDispatchOccupancy().queued
      !== basePolicy.channel.maxQueuedVerificationDispatches
      || flow.service.mailDispatchOccupancy().inFlight
        !== basePolicy.channel.maxConcurrentVerificationDispatches) {
